class Solution {
public:
    vector<int> resultsArray(vector<int>& nums, int k) {
        if (k == 1) return nums;
        int n = nums.size();
        vector<int> ans;
        int consec = 1;
        for (int i = 1; i < n; ++i) {
            if (nums[i] == nums[i - 1] + 1) {
                consec++;
            } else {
                consec = 1;
            }
            if (i >= k - 1) {
                ans.push_back((consec >= k) ? nums[i] : -1);
            }
        }
        return ans;
    }
};

class Solution {
    public int[] resultsArray(int[] nums, int k) {
        if (k == 1) return nums.clone();
        int n = nums.length;
        int[] ans = new int[n - k + 1];
        int consec = 1;
        for (int i = 1; i < n; ++i) {
            if (nums[i] == nums[i - 1] + 1) {
                consec++;
            } else {
                consec = 1;
            }
            if (i >= k - 1) {
                ans[i - (k - 1)] = (consec >= k) ? nums[i] : -1;
            }
        }
        return ans;
    }
}

